// The roster (plan §10.1, §10.5): 58 named, recurring adults. Data only. Looks are built from the
// two player bodies (src/character/character.ts): hairstyles per body, garments from the item
// catalog (anyone can wear anything), skin swatch index, and a height scale. Dialogue trees and
// bark overrides live in src/data/dialogue/*.ts keyed by the same ids.
import type { ItemStack } from '../sim/inventory.ts';

export type Archetype = 'camper' | 'hiker' | 'partier' | 'thief' | 'waterwalker' | 'ranger' | 'oddball';
export type Armed = 'none' | 'knife' | 'handgun' | 'rifle';

export interface NpcLook {
  sex: 'male' | 'female';
  /** SKIN_SWATCHES index 0..9. */
  skin: number;
  hairStyle: string;
  hairColor: string;
  outfit: { top?: string; bottom?: string; full?: string; shoes?: string; hat?: string };
  /** Garment id → CSS colour. */
  colors: Record<string, string>;
  /** Root scale (height variety), ~0.9–1.12. */
  scale: number;
}

export interface NpcVoice {
  /** Blip pitch multiplier. */
  pitch: number;
  /** Blip rate multiplier. */
  speed: number;
  timbre: 'sine' | 'triangle' | 'square' | 'sawtooth';
}

export interface NpcTrading {
  /** Item ids or `kind:<ItemKind>` tags valued ×2. */
  wants: readonly string[];
  /** Valued ×3. */
  favorite?: string;
  /** Valued ×0.25. */
  dislikes: readonly string[];
  /** Never accepted. */
  refuses: readonly string[];
  /** 0..1: the premium they demand over their own items' value. */
  greed: number;
  /** What they bring to the table. */
  stock: readonly ItemStack[];
}

export interface NpcDef {
  id: string;
  name: string;
  archetypes: readonly Archetype[];
  armed: Armed;
  look: NpcLook;
  voice: NpcVoice;
  traits: readonly string[];
  catchphrases: readonly string[];
  gag: string;
  trading?: NpcTrading;
  /** Carried items (thief getaway loot bags, poof drops). */
  loot: readonly ItemStack[];
  /** Thief specialities (§11.4): `only` restricts what they take (tags), `prefers` weights ×3. */
  theft?: { only?: readonly string[]; prefers?: readonly string[] };
  schedule: { day: number; night: number; areas: readonly string[] };
  links?: readonly string[];
}

