const H = { black: '#1b1512', darkBrown: '#3b2416', brown: '#6b4423', chestnut: '#a0673a', auburn: '#c98a4a', blonde: '#d9b26a', platinum: '#f1e2b0', red: '#b8412a', silver: '#9a9a9a', blue: '#3b6fd9', purple: '#b03aa8', green: '#2fa66a' } as const;

const ALL_AREAS = ['switchback', 'pool', 'cedar_bridge', 'campground', 'plank_bridge', 'sandy_bend', 'dock', 'suspension_bridge', 'marsh'] as const;
const WATER_AREAS = ['pool', 'sandy_bend', 'dock', 'marsh', 'campground'] as const;

type Partial2<T> = { [K in keyof T]?: T[K] };
function npc(d: Partial2<NpcDef> & { id: string; name: string; archetypes: readonly Archetype[]; look: NpcLook; voice: NpcVoice; gag: string; catchphrases: readonly string[] }): NpcDef {
  return { armed: 'none', traits: [], loot: [], schedule: { day: 1, night: 0.4, areas: ALL_AREAS }, ...d };
}

