export const NPC_BY_ID: ReadonlyMap<string, NpcDef> = new Map(NPCS.map((n) => [n.id, n]));

export function npcDef(id: string): NpcDef {
  const n = NPC_BY_ID.get(id);
  if (!n) throw new Error(`unknown npc ${id}`);
  return n;
}

export function isKnownNpc(id: unknown): id is string {
  return typeof id === 'string' && NPC_BY_ID.has(id);
}

export function npcsOfArchetype(a: Archetype): NpcDef[] {
  return NPCS.filter((n) => n.archetypes.includes(a));
}

